mkdir -p /tmp/work && cat > /tmp/work/r.py <<'EOF'
import json,time,urllib.request,urllib.error
from datetime import datetime,timezone
B="http://localhost:8080";tok=None;log={}
def newtok():
    global tok
    while True:
        try:
            r=urllib.request.urlopen(urllib.request.Request(B+"/token",method="POST"));tok=json.load(r)["token"];return
        except urllib.error.HTTPError as e:
            if e.code==429: time.sleep(float(e.headers.get("Retry-After") or 1))
            else: time.sleep(1)
def get(p):
    if tok is None: newtok()
    while True:
        try: return json.load(urllib.request.urlopen(urllib.request.Request(B+p,headers={"Authorization":"Bearer "+tok})))
        except urllib.error.HTTPError as e:
            log[e.code]=log.get(e.code,0)+1
            if e.code==401: newtok()
            elif e.code==429: time.sleep(float(e.headers.get("Retry-After") or 1))
            elif e.code==404 and p.startswith("/customers"): return None
            else: time.sleep(0.5)
        except Exception as e: log['x']=log.get('x',0)+1; time.sleep(0.5)
seen={};dups=0;p="/orders?page=1";pages=0
while p:
    d=get(p);pages+=1
    for o in d["items"]:
        if o["id"] in seen: dups+=1
        else: seen[o["id"]]=o
    p=d["next"]
lo=datetime(2025,3,1,tzinfo=timezone.utc);hi=datetime(2025,6,1,tzinfo=timezone.utc)
cust={};reg={k:0 for k in["north","south","east","west"]};n=0;odd=[]
statuses=set()
for o in seen.values():
    statuses.add(o["status"])
    if o["status"]!="shipped": continue
    t=datetime.fromisoformat(o["placed_at"].replace("Z","+00:00"))
    if t.tzinfo is None: t=t.replace(tzinfo=timezone.utc); odd.append(("naive",o["id"]))
    t=t.astimezone(timezone.utc)
    if not(lo<=t<hi): continue
    c=o["customer_id"]
    if c not in cust: cust[c]=get(f"/customers/{c}")
    cu=cust[c]
    if cu is None: odd.append(("nocust",o["id"],c)); continue
    v=(o["amount_cents"]*(100-cu["discount_pct"])+50)//100
    reg[cu["region"]]+=v;n+=1
print(pages,len(seen),dups,statuses,log,odd[:10],len(odd))
json.dump({"total_cents":sum(reg.values()),"order_count":n,"duplicates_skipped":dups,"by_region":reg},open("/workspace/result.json","w"),indent=2)
EOF
python3 -I /tmp/work/r.py; cat /workspace/result.json

